void reverse(struct DoublyLinkedList* list) {
    if (!list->head || !list->head->next) return;

    struct DoubleLinkedListNode* current = list->head;
    struct DoubleLinkedListNode* previous = NULL;

    while (current) {
        struct DoubleLinkedListNode* next_node = current->next;
        current->next = previous;
        current->prev = next_node;

        previous = current;
        current = next_node;
    }

    list->head = previous;
