    int capacity;
    pthread_mutex_t lock;
    int current_threads;
    int max_threads;
} ThreadPool;

void* task_wrapper(void* arg) {
    Task* task = (Task*)arg;
    task->task_func(task->arg);
    return NULL;
}

void add_thread(ThreadPool* pool, void (*task_func)(void*), void* arg) {
    pthread_mutex_lock(&pool->lock);
    if (pool->current_threads < pool->max_threads) {
        pthread_t thread;
